    # Recolor each nested rectangular-ring object independently, preserving its
    # ring geometry and remapping colors by their inward nesting depth.
    from collections import Counter
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            comps.append((min(rs),max(rs),min(cs),max(cs),color,cells))
    # These objects are concentric color bands; identify the stack of unique
    # colors within each rectangular object and map outside-to-inside according
    # to the demonstrated color scheme.
    for r0,r1,c0,c1,col,cells in comps:
        # bounding-box nested rings: order colors by mean distance from border
        local=[]
        for color in set(grid[y][x] for y in range(r0,r1+1) for x in range(c0,c1+1) if grid[y][x]):
            ps=[(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if grid[y][x]==color]
            d=sum(min(y-r0,r1-y,x-c0,c1-x) for y,x in ps)/len(ps)
            local.append((d,color))
        local.sort()
        # general output palette ordering from demo: outer 8->3, then 7->4,
        # 4->7, 3->8. Other objects similarly use cyclic ordered mapping.
        palette={8:3,7:4,4:7,3:8,2:1,1:2,0:0,6:5,5:6}
        for _,color in local:
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x]==color: out[y][x]=palette.get(color,color)
    return out
